{
  "root": "main",
  "state": {
    "schedule": [
      { "day": "Monday", "time": "90 min", "focus": "Cell structure basics", "technique": "Label-from-memory diagram; flashcards", "checklist": "Can label organelles and state each function" },
      { "day": "Tuesday", "time": "90 min", "focus": "Cell membranes and transport", "technique": "Blank-diagram redraw; teach it aloud", "checklist": "Can explain diffusion, osmosis, active transport" },
      { "day": "Wednesday", "time": "90 min", "focus": "Genetics: DNA, genes, chromosomes", "technique": "Closed-notes summary; retrieval quiz", "checklist": "Can define DNA, gene, allele, chromosome" },
      { "day": "Thursday", "time": "90 min", "focus": "Genetics: inheritance and Punnett squares", "technique": "Solve from memory; error correction", "checklist": "Can complete monohybrid crosses accurately" },
      { "day": "Friday", "time": "90 min", "focus": "Genetics: mutations and traits review", "technique": "Mixed practice set; explain answers", "checklist": "Can distinguish mutation types and inheritance patterns" },
      { "day": "Saturday", "time": "30–40 min", "focus": "Quick review: cell structure + genetics", "technique": "Flashcard sprint; 5-minute brain dump", "checklist": "Can recall key terms without notes" },
      { "day": "Sunday", "time": "30–40 min", "focus": "Quick review: evolution + full recap", "technique": "Mini mock quiz; self-correction", "checklist": "Can explain natural selection and identify weak spots" }
    ]
  },
  "elements": {
    "main": {
      "type": "Stack",
      "props": { "direction": "vertical", "gap": "md", "padding": 16 },
      "children": ["title", "intro", "roadmap", "actions", "sources"]
    },
    "title": { "type": "Text", "props": { "text": "One-Week Biology Exam Study Plan", "variant": "h1" }, "children": [] },
    "intro": { "type": "Text", "props": { "text": "A focused 7-day plan for cell structure, genetics, and evolution, built around 90 minutes on weekdays plus two short weekend review sessions. Genetics gets the most time and repetition.", "variant": "body" }, "children": [] },
    "roadmap": {
      "type": "Table",
      "props": {
        "domain": "schedule",
        "preferredPresentation": "cards",
        "primaryColumn": "day",
        "highlightColumns": ["focus"],
        "statePath": "/schedule",
        "columns": [
          { "key": "day", "label": "Day" },
          { "key": "time", "label": "Time" },
          { "key": "focus", "label": "Focus" },
          { "key": "technique", "label": "Active Recall Technique" },
          { "key": "checklist", "label": "Self-Test Checklist" }
        ]
      },
      "children": []
    },
    "actions": {
      "type": "Stack",
      "props": { "direction": "horizontal", "gap": "sm", "wrap": "wrap" },
      "children": ["btn1", "btn2", "btn3"]
    },
    "btn1": { "type": "Button", "props": { "label": "Print Plan", "on": { "press": { "action": "openUrl", "params": { "url": "https://www.canva.com/" } } } }, "children": [] },
    "btn2": { "type": "Button", "props": { "label": "Make Flashcards", "on": { "press": { "action": "openUrl", "params": { "url": "https://quizlet.com/" } } } }, "children": [] },
    "btn3": { "type": "Button", "props": { "label": "Practice Quiz", "on": { "press": { "action": "openUrl", "params": { "url": "https://www.khanacademy.org/science/biology" } } } }, "children": [] },
    "sources": {
      "type": "Stack",
      "props": { "direction": "vertical", "gap": "sm" },
      "children": ["srcTitle", "src1", "src2", "src3"]
    },
    "srcTitle": { "type": "Text", "props": { "text": "Sources", "variant": "h3" }, "children": [] },
    "src1": { "type": "Button", "props": { "label": "Biology study support", "variant": "borderless", "on": { "press": { "action": "openUrl", "params": { "url": "https://www.khanacademy.org/science/biology" } } } }, "children": [] },
    "src2": { "type": "Button", "props": { "label": "Flashcard practice", "variant": "borderless", "on": { "press": { "action": "openUrl", "params": { "url": "https://quizlet.com/" } } } }, "children": [] },
    "src3": { "type": "Button", "props": { "label": "Study planning tool", "variant": "borderless", "on": { "press": { "action": "openUrl", "params": { "url": "https://www.canva.com/" } } } }, "children": [] }
  }
}
